"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2444],{82444:e=>{e.exports=JSON.parse('{"slug":"semeynaya-ipoteka-oktyabr-2026-stavki","locale":"en","title":"Family mortgage rates for one-child households rise from 6% to 10–12%","description":"From October 1, 2026, family mortgage rates range from 2% to 12% depending on children and region. How payments change and who is unaffected.","blocks":[{"id":"b001","kind":"paragraph","text":"From October 1, 2026, rates under the Family Mortgage program depend on the number of children. Previously everyone paid 6%. A one-child family now pays 10% in the regions and 12% in Moscow, St Petersburg, Moscow Region and Leningrad Region. Each additional child lowers the rate by 2 points, reaching 2% in the regions and 4% in the capitals for five children."},{"id":"b002","kind":"paragraph","text":"From October 1, family mortgage loan limits also depend on the number of children. In the regions, they are 6 million rubles for one child, 8 million for two and 10 million for three or more. In Moscow, St Petersburg and surrounding regions, they are 12, 15 and 18 million rubles. At least one child must be younger than 7. The down payment remains at least 20%, and maternity capital can fund it."},{"id":"b003","kind":"paragraph","text":"Rates no higher than 6%, regardless of the number of children, remain available in two cases: families with a child with disabilities, and those paying at least half the home price from their own funds or reducing debt to 50% within a year after purchase. The new terms apply only to contracts from October 1, 2026. Earlier family mortgages are unaffected."},{"id":"b004","kind":"paragraph","text":"How the subsidy works: the bank lends at a low rate and the state pays the difference up to the market rate. This is interest-rate subsidization. The higher the Bank of Russia\'s key rate, currently 14%, the more the budget pays per subsidized loan. Under the new rules, the state subsidizes only the first 15 years, rather than the entire term as before. After 15 years, the rate may rise to the market level."},{"id":"b005","kind":"paragraph","text":"The ruble difference is substantial. A 6 million ruble mortgage for 30 years at 6% costs about 36 thousand rubles a month. At 10%, now applicable to a one-child regional family, the same loan costs about 52.7 thousand rubles during the first 15 years, an extra 16.7 thousand. A three-child family\'s regional rate remains 6%, while in Moscow and St Petersburg it rises to 8%. The subsidy is still large: on September 24, 2026, the full cost of ordinary mortgages at major banks was about 22% annually."},{"id":"b006","kind":"paragraph","text":"What remains unknown is how the new rules will affect demand and new-build prices. A one-child family borrowing at 10–12% in expectation of quick refinancing is betting on key-rate cuts nobody has promised; the Bank of Russia\'s next decision is October 23. Postponing a purchase also costs money because rent continues. A down payment of at least half the price restores a 6% rate but consumes the emergency reserve."},{"id":"b007","kind":"heading","text":"What family mortgage rates apply from October 1, 2026?"},{"id":"b008","kind":"paragraph","text":"In the regions: 10% with one child, 8% with two, 6% with three, 4% with four and 2% with five or more. Moscow, St Petersburg and their surrounding regions charge 2 points more, from 12% to 4%."},{"id":"b009","kind":"heading","text":"Will an existing family mortgage rate change?"},{"id":"b010","kind":"paragraph","text":"No. The new terms apply only to contracts concluded from October 1, 2026. Earlier loans retain their previous 6% rate."},{"id":"b011","kind":"heading","text":"Can a one-child family obtain a 6% family mortgage?"},{"id":"b012","kind":"paragraph","text":"Yes, in two cases: a family has a child with disabilities, or pays at least half the home price from its own funds or reduces the debt to 50% within a year after purchase."}],"sources":[{"label":"Family mortgages linked to the number of children","url":"https://lenta.ru/news/2026/10/01/long-sem-ipo"},{"label":"Family mortgages from October 1, 2026: new rates, limits and terms","url":"https://finance.mail.ru/article/semejnaya-ipoteka-po-novym-usloviyam-chto-menyaetsya-s-1-oktyabrya-69230142/"},{"label":"Family mortgages from October 1, 2026: all new terms","url":"https://bankinform.ru/news/143196"},{"label":"Family mortgage terms change from October 1, 2026","url":"https://rb.ru/news/usloviya-po-semejnoj-ipoteke-izmenyatsya-s-1-oktyabrya-2026-goda-stavka-budet-privyazana-k-kolichestvu-detej/"},{"label":"Family mortgages from October 1, 2026: rates and limits by number of children","url":"https://finuslugi.ru/navigator/kak-ehto-rabotaet/stat_semeynaya-ipoteka-menyaetsya-s-1-iyulya"},{"label":"Mortgage costs stall in September 2026","url":"https://brobank.ru/stoimost-ipoteki-sentyabr-2026-goda/"},{"label":"The Bank of Russia kept the key rate at 14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"910527a74fa7b29390aaa229e3ba15e4be6028a23c1921d265fdaa19884579bc"}')}}]);